import{_ as t,a0 as o,w as d,s as r,I as n,x as e,a1 as l,A as i,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用 Ansible 管理你的工作站：配置桌面設置 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Ansible 管理你的工作站：配置桌面設置 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Ansible 管理你的工作站：配置桌面設置 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Ansible 管理你的工作站：配置桌面設置 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20180529 Manage your workstation with Ansible- Configure desktop settings","title":"使用 Ansible 管理你的工作站：配置桌面設置","tag":"201907","desc":""},"relativePath":"201907/20180529 Manage your workstation with Ansible- Configure desktop settings.md","filePath":"[post].md"}'),u={name:"201907/20180529 Manage your workstation with Ansible- Configure desktop settings.md"};function g(c,s,k,b,h,m){const a=o("Link");return d(),r("div",null,[s[38]||(s[38]=n("h1",{id:"使用-ansible-管理你的工作站-配置桌面設置",tabindex:"-1"},[e("使用 Ansible 管理你的工作站：配置桌面設置 "),n("a",{class:"header-anchor",href:"#使用-ansible-管理你的工作站-配置桌面設置","aria-label":"Permalink to “使用 Ansible 管理你的工作站：配置桌面設置”"},"​")],-1)),s[39]||(s[39]=n("blockquote",null,[n("p",null,"在本系列第三篇（也是最後一篇）文章中，我們將使用 Ansible 自動化配置 GNOME 桌面設置。")],-1)),s[40]||(s[40]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/cube_innovation_process_block_container.png?itok=vkPYmSRQ",alt:""})],-1)),n("p",null,[s[2]||(s[2]=e("在本系列關於使用 Ansible 配置工作站的",-1)),l(a,{href:"https://linux.cn/article-10434-1.html"},{default:i(()=>[...s[0]||(s[0]=[e("第一篇文章",-1)])]),_:1}),s[3]||(s[3]=e("中，我們設置了一個倉庫並配置了一些基本的東西。在",-1)),l(a,{href:"https://linux.cn/article-10449-1.html"},{default:i(()=>[...s[1]||(s[1]=[e("第二篇文章",-1)])]),_:1}),s[4]||(s[4]=e("中，我們配置了 Ansible 以使其在對倉庫進行更改時自動應用設置。在第三篇（也是最後一篇）文章中，我們將使用 Ansible 配置 GNOME 桌面設置。",-1))]),s[41]||(s[41]=n("p",null,[e("此配置只適用於較新的發行版（例如我將在示例中使用的 Ubuntu 18.04）。較舊版本的 Ubuntu 將無法運行，因為它們附帶了一個老版本的 "),n("code",null,"python-psutils"),e("，對於 Ansible 的 "),n("code",null,"dconf"),e(" 模組無法正常工作。如果你使用的是較新版本的 Linux 發行版，則應該沒有問題。")],-1)),n("p",null,[s[6]||(s[6]=e("在開始之前，確保你已經完成了本系列的第一部分和第二部分，因為第三部分建立在此基礎之上的。如果還沒有，下載前兩篇文章中一直使用的 GitHub ",-1)),l(a,{href:"https://github.com/jlacroix82/ansible_article.git"},{default:i(()=>[...s[5]||(s[5]=[e("倉庫",-1)])]),_:1}),s[7]||(s[7]=e("，我們將為其添加更多功能。",-1))]),s[42]||(s[42]=p(`<h3 id="設置壁紙和鎖屏" tabindex="-1">設置壁紙和鎖屏 <a class="header-anchor" href="#設置壁紙和鎖屏" aria-label="Permalink to “設置壁紙和鎖屏”">​</a></h3><p>首先，我們將創建一個任務手冊來保存我們的 GNOME 設置。在倉庫的根目錄中，應該有一個名為 <code>local.yml</code> 的文件，添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- include: tasks/gnome.yml</span></span></code></pre></div><p>整個文件應如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- hosts: localhost</span></span>
<span class="line"><span>  become: true</span></span>
<span class="line"><span>  pre_tasks:</span></span>
<span class="line"><span>    - name: update repositories</span></span>
<span class="line"><span>      apt: update_cache=yes</span></span>
<span class="line"><span>      changed_when: False</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  tasks:</span></span>
<span class="line"><span>    - include: tasks/users.yml</span></span>
<span class="line"><span>    - include: tasks/cron.yml</span></span>
<span class="line"><span>    - include: tasks/packages.yml</span></span>
<span class="line"><span>    - include: tasks/gnome.yml</span></span></code></pre></div><p>基本上，這添加了對名為 <code>gnome.yml</code> 文件的引用，它將存儲在倉庫內的 <code>tasks</code> 目錄中。我們還沒有創建這個文件，現在就來創建它。在 <code>tasks</code> 目錄中創建 <code>gnome.yml</code> 文件，並將以下內容放入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Install python-psutil package</span></span>
<span class="line"><span>  apt: name=python-psutil</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Copy wallpaper file</span></span>
<span class="line"><span>  copy: src=files/wallpaper.jpg dest=/home/jay/.wallpaper.jpg owner=jay group=jay mode=600</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Set GNOME Wallpaper</span></span>
<span class="line"><span>  become_user: jay</span></span>
<span class="line"><span>  dconf: key=&quot;/org/gnome/desktop/background/picture-uri&quot; value=&quot;&#39;file:///home/jay/.wallpaper.jpg&#39;&quot;</span></span></code></pre></div><p>注意，此代碼多次引用我的用户名（<code>jay</code>），因此確保使用你機器上的用户名替換每次出現的 <code>jay</code>。另外，如果你沒有像我一樣使用 Ubuntu 18.04，你將必須更改 <code>apt</code> 一行來匹配你所選擇的發行版的包管理器，並確認 <code>python-psutil</code> 包的名稱，因為它可能有所不同。</p>`,8)),n("p",null,[s[9]||(s[9]=e("在示例任務中，我引用了 ",-1)),s[10]||(s[10]=n("code",null,"file",-1)),s[11]||(s[11]=e(" 目錄下的 ",-1)),s[12]||(s[12]=n("code",null,"wallpaper.jpg",-1)),s[13]||(s[13]=e(" 文件，此文件必須存在，否則 Ansible 配置將失敗。在 ",-1)),s[14]||(s[14]=n("code",null,"tasks",-1)),s[15]||(s[15]=e(" 目錄中，創建一個名為 ",-1)),s[16]||(s[16]=n("code",null,"files",-1)),s[17]||(s[17]=e(" 的子目錄。找到你喜歡的壁紙圖片，將其命名為 ",-1)),s[18]||(s[18]=n("code",null,"wallpaper.jpg",-1)),s[19]||(s[19]=e("，然後把它放在 ",-1)),s[20]||(s[20]=n("code",null,"files",-1)),s[21]||(s[21]=e(" 目錄中。如果文件是 PNG 圖像而不是 JPG，在代碼和倉庫中更改文件擴展名。如果你覺得沒有創意，我在 ",-1)),l(a,{href:"https://github.com/jlacroix82/ansible_article.git"},{default:i(()=>[...s[8]||(s[8]=[e("GitHub 倉庫",-1)])]),_:1}),s[22]||(s[22]=e(" 中有一個示例壁紙文件，你可以使用它。",-1))]),s[43]||(s[43]=p(`<p>完成所有這些更改後，將內容提交到 GitHub 倉庫，並推送這些更改。總結一下，你應該完成以下工作：</p><ul><li>修改 <code>local.yml</code> 文件以引用 <code>tasks/gnome.yml</code></li><li>使用上面提到的內容創建 <code>tasks/gnome.yml</code></li><li>在 <code>tasks</code> 目錄中創建一個 <code>files</code> 目錄，其中有一個名為 <code>wallpaper.jpg</code> 的圖像文件（或者你選擇的任何名稱）。</li></ul><p>完成這些步驟並將更改推送到倉庫後，配置應該在下次計劃運行期間自動應用。（你可能還記得我們在上一篇文章中對此進行了自動化。）如果你想節省時間，可以使用以下命令立即應用配置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ansible-pull -U https://github.com/&lt;github_user&gt;/ansible.git</span></span></code></pre></div><p>如果一切正常，你應該可以看到你的新壁紙。</p><p>讓我們花一點時間來了解新的 GNOME 任務手冊的功能。首先，我們添加了一個計劃來安裝 <code>python-psutil</code> 包。如果不添加它，我們就不能使用 <code>dconf</code> 模組，因為它需要在修改 GNOME 設置之前安裝這個包。接下來，我們使用 <code>copy</code> 模組將壁紙文件複製到我們的 <code>home</code> 目錄，並將生成的文件命名為以點開頭的隱藏文件。如果你不希望此文件放在 <code>home</code> 目錄的根目錄中，你可以隨時指示此部分將其複製到其它位置 —— 只要你在正確的位置引用它，它仍然可以工作。在下一個計劃中，我們使用 <code>dconf</code> 模組來更改 GNOME 設置。在這種情況下，我們調整了 <code>/org/gnome/desktop/background/picture-uri</code> 鍵並將其設置為 <code>file:///home/jay/.wallpaper.jpg</code>。注意本節中的引號 —— 你必須在 <code>dconf</code> 值中使用兩個單引號，如果值是一個字符串，還必須包含在雙引號內。</p><p>現在，讓我們進一步進行配置，並將背景應用於鎖屏。這是現在的 GNOME 任務手冊，但增加了兩個額外的計劃：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Install python-psutil package</span></span>
<span class="line"><span>  apt: name=python-psutil</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Copy wallpaper file</span></span>
<span class="line"><span>  copy: src=files/wallpaper.jpg dest=/home/jay/.wallpaper.jpg owner=jay group=jay mode=600</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Set GNOME wallpaper</span></span>
<span class="line"><span>  dconf: key=&quot;/org/gnome/desktop/background/picture-uri&quot; value=&quot;&#39;file:///home/jay/.wallpaper.jpg&#39;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Copy lockscreenfile</span></span>
<span class="line"><span>  copy: src=files/lockscreen.jpg dest=/home/jay/.lockscreen.jpg owner=jay group=jay mode=600</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- name: Set lock screen background</span></span>
<span class="line"><span>  become_user: jay</span></span>
<span class="line"><span>  dconf: key=&quot;/org/gnome/desktop/screensaver/picture-uri&quot; value=&quot;&#39;file:///home/jay/.lockscreen.jpg&#39;&quot;</span></span></code></pre></div><p>正如你所看到的，我們做的事情和設置壁紙時差不多。我們添加了兩個額外的任務，一個是複製鎖屏圖像並將其放在我們的 <code>home</code> 目錄中，另一個是將設置應用於 GNOME 以便使用它。同樣，確保將 <code>jay</code> 更改為你的用户名，並命名你想要的鎖屏圖片 <code>lockscreen.jpg</code>，並將其複製到 <code>files</code> 目錄。將這些更改提交到倉庫後，在下一次計劃的 Ansible 運行期間就會應用新的鎖屏。</p><h3 id="應用新的桌面主題" tabindex="-1">應用新的桌面主題 <a class="header-anchor" href="#應用新的桌面主題" aria-label="Permalink to “應用新的桌面主題”">​</a></h3><p>設置壁紙和鎖屏背景很酷，但是讓我們更進一步來應用桌面主題。首先，讓我們在我們的任務手冊中添加一條指令來安裝 <code>arc</code> 主題的包。將以下代碼添加到 GNOME 任務手冊的開頭：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Install arc theme</span></span>
<span class="line"><span>  apt: name=arc-theme</span></span></code></pre></div><p>然後，在底部，添加以下動作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>- name: Set GTK theme</span></span>
<span class="line"><span>  become_user: jay</span></span>
<span class="line"><span>  dconf: key=&quot;/org/gnome/desktop/interface/gtk-theme&quot; value=&quot;&#39;Arc&#39;&quot;</span></span></code></pre></div><p>你看到 GNOME 的 GTK 主題在你眼前變化了嗎？我們添加了一個動作來通過 <code>apt</code> 模組安裝 <code>arc-theme</code> 包，另一個動作將這個主題應用到 GNOME。</p><h3 id="進行其它定製" tabindex="-1">進行其它定製 <a class="header-anchor" href="#進行其它定製" aria-label="Permalink to “進行其它定製”">​</a></h3><p>既然你已經更改了一些 GNOME 設置，你可以隨意添加其它定製。你在 GNOME 中調整的任何設置都可以通過這種方式自動完成，設置壁紙和主題只是幾個例子。你可能想知道如何找到要更改的設置，以下是一個我用的技巧。</p><p>首先，通過在你管理的計算機上運行以下命令，獲取所有當前 <code>dconf</code> 設置的快照：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dconf dump / &gt; before.txt</span></span></code></pre></div><p>此命令將所有當前更改導出到名為 <code>before.txt</code> 的文件中。接下來，手動更改要自動化的設置，並再次獲取 <code>dconf</code> 設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dconf dump / &gt; after.txt</span></span></code></pre></div><p>現在，你可以使用 <code>diff</code> 命令查看兩個文件之間的不同之處：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>diff before.txt after.txt</span></span></code></pre></div><p>這應該會給你一個已更改鍵值的列表。雖然手動更改設置確實違背了自動化的目的，但你實際上正在做的是獲取更新首選設置時更改的鍵，這允許你創建 Ansible 任務以修改這些設置，這樣你就再也不需要碰這些設置了。如果你需要還原機器，Ansible 倉庫會處理好你的每個定製。如果你有多台計算機，甚至是一組工作站，則只需手動進行一次更改，所有其他工作站都將應用新設置並完全同步。</p><h3 id="最後" tabindex="-1">最後 <a class="header-anchor" href="#最後" aria-label="Permalink to “最後”">​</a></h3><p>如果你已經閲讀完本系列文章，你應該知道如何設置 Ansible 來自動化工作站。這些示例提供了一個有用的基礎，你可以使用這些語法和示例進行其他定製。隨着你的進展，你可以繼續添加新的修改，這將使你的 Ansible 配置一直增長。</p><p>我已經用 Ansible 以這種方式自動化了一切，包括我的用户帳户和密碼、Vim、tmux 等配置文件、桌面包、SSH 設置、SSH 密鑰，基本上我想要自定義的一切都使用了。以本系列文章作為起點，將為你實現工作站的完全自動化鋪平道路。</p><hr>`,28)),n("p",null,[s[24]||(s[24]=e("via: ",-1)),l(a,{href:"https://opensource.com/article/18/5/manage-your-workstation-ansible-part-3"},{default:i(()=>[...s[23]||(s[23]=[e("https://opensource.com/article/18/5/manage-your-workstation-ansible-part-3",-1)])]),_:1})]),n("p",null,[s[29]||(s[29]=e("作者：",-1)),l(a,{href:"https://opensource.com/users/jlacroix"},{default:i(()=>[...s[25]||(s[25]=[e("Jay LaCroix",-1)])]),_:1}),s[30]||(s[30]=e(" 選題：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[26]||(s[26]=[e("lujun9972",-1)])]),_:1}),s[31]||(s[31]=e(" 譯者：",-1)),l(a,{href:"https://github.com/MjSeven"},{default:i(()=>[...s[27]||(s[27]=[e("MjSeven",-1)])]),_:1}),s[32]||(s[32]=e(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[28]||(s[28]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[35]||(s[35]=e("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[33]||(s[33]=[e("LCTT",-1)])]),_:1}),s[36]||(s[36]=e(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:i(()=>[...s[34]||(s[34]=[e("Linux中國",-1)])]),_:1}),s[37]||(s[37]=e(" 榮譽推出",-1))])])}const j=t(u,[["render",g]]);export{C as __pageData,j as default};
